# template from original 1s blob
cells=[(r,c) for r in range(H) for c in range(W) if inp[r][c]==1]
rs=[r for r,c in cells]; cs=[c for r,c in cells]
T={(r-min(rs),c-min(cs)) for r,c in cells}
print(sorted(T), max(rs)-min(rs)+1, max(cs)-min(cs)+1)
def matches(zmask, T):
    th=max(r for r,c in T)+1; tw=max(c for r,c in T)+1
    res=set()
    for r in range(H-th+1):
        for c in range(W-tw+1):
            if all((r+dr,c+dc) in zmask for dr,dc in T):
                res.add((r,c))
    return res
zset={(r,c) for r in range(H) for c in range(W) if inp[r][c]==0}
occ = matches(zset,T)
pred = {(r+dr,c+dc) for r,c in occ for dr,dc in T}
actual = {(r,c) for r,c in new1}
print("occurrences:", sorted(occ))
print("pred==actual:", pred==actual, "missing:", sorted(actual-pred), "extra:", sorted(pred-actual))
